      "path": "cordis.patch.yml",
      "content": "# MCP连接器 插件（DSH Bundle patch）\n# 作为 bundle 被合入 profile 时，自动插入本插件行。\n# 插件负责连接器目录、三通道连接、凭证存储与 mcp-client 条目动态配置。\n- insert:\n    - id: mcp-connector\n      name: 'dsh-mcp-connector'\n      config:\n        catalogUrl: 'https://cdn.jsdelivr.net/gh/duhu2000/dsh-mcp-connector-registry@main/catalog.json'\n        persistSecrets: true\n        entryPrefix: 'mcp'\n        refreshSkewMs: 300000\n        openBrowser: true\n        showSidebarEntry: true\n        # true：仅注册发现与会话两个管理入口；完整连接配置仍在界面操作。\n        # 保持 false 兼容已有对话/自动化；更改后重载插件。\n        compactManagementTools: false\n        # 面板 CSP frame-ancestors 白名单：默认仅同源可嵌入。\n        # 桌面壳（Tauri/Electron）内嵌面板时需显式追加外壳源，\n        # 例如 ['self', 'http://tauri.localhost', 'tauri://localhost']。\n        frameAncestors: ['self']\n"
    },
