      "path": "lib/mcp-http.js",
      "content": "/**\n * Streamable HTTP MCP 会话客户端。\n *\n * 详情页不能直接向有状态的 MCP Server 发送 tools/list：必须先\n * initialize，保留响应的 Mcp-Session-Id，发送 notifications/initialized，\n * 再在后续每个请求中携带会话头和凭据。\n */\nimport { MCP_PROTOCOL_VERSION } from './constants.js';\nimport { authHeaders } from './mcp-provision.js';\nimport { parseRetryAfter } from './discovery-policy.js';\nimport { readSseResponse } from './mcp-sse.js';\nimport { DEFAULT_LOCALE, createTranslator } from './i18n/index.js';\n\n/** 缺省译文：中文（既有调用点与测试无需改动）。 */\nconst tZh = createTranslator(DEFAULT_LOCALE);\n\nconst MAX_RESPONSE_BYTES = 2 * 1024 * 1024;\nconst MAX_TOOL_PAGES = 100;\nconst MAX_TOOLS = 10_000;\n\nexport class McpHttpError extends Error {\n  constructor(message, { kind = 'protocol', status, retryAfterMs } = {}) {\n    super(message);\n    this.name = 'McpHttpError';\n    this.kind = kind;\n    this.status = status;\n    this.retryAfterMs = retryAfterMs;\n  }\n}\n\nasync function readLimitedText(response, maxBytes = MAX_RESPONSE_BYTES, { t = tZh } = {}) {\n  const declared = Number(response.headers.get('content-length'));\n  if (Number.isFinite(declared) && declared > maxBytes) throw new McpHttpError(t('MCP 响应过大'));\n  if (!response.body) return '';\n  const reader = response.body.getReader();\n  const chunks = [];\n  let total = 0;\n  for (;;) {\n    const { done, value } = await reader.read();\n    if (done) break;\n    total += value.byteLength;\n    if (total > maxBytes) {\n      await reader.cancel().catch(() => {});\n      throw new McpHttpError(t('MCP 响应过大'));\n    }\n    chunks.push(value);\n  }\n  const bytes = new Uint8Array(total);\n  let offset = 0;\n  for (const chunk of chunks) {\n    bytes.set(chunk, offset);\n    offset += chunk.byteLength;\n  }\n  return new TextDecoder().decode(bytes);\n}\n\nfunction parseMcpPayload(text, contentType = '') {\n  if (contentType.includes('text/event-stream')) {\n    for (const line of text.split(/\\r?\\n/)) {\n      if (!line.startsWith('data:')) continue;\n      try { return JSON.parse(line.slice(5).trim()); } catch {}\n    }\n    return undefined;\n  }\n  try { return JSON.parse(text); } catch { return undefined; }\n}\n\nfunction responseError(response, payload, text, { t = tZh } = {}) {\n  const rawMessage = String(payload?.error?.message ?? text ?? '').replace(/\\s+/g, ' ').trim().slice(0, 180);\n  if (response.status === 401 || response.status === 403) {\n    return new McpHttpError(t('凭据无效、已过期或权限不足（HTTP {status}）', { status: response.status }), { kind: 'auth', status: response.status });\n  }\n  if (response.status === 429) {\n    return new McpHttpError(t('服务请求过于频繁（HTTP 429），请稍后重试'), { kind: 'rate-limit', status: response.status, retryAfterMs: parseRetryAfter(response.headers.get('retry-after')) });\n  }\n  const suffix = rawMessage ? `${t('：')}${rawMessage}` : '';\n  return new McpHttpError(t('MCP 请求失败（HTTP {status}）{suffix}', { status: response.status, suffix }), { kind: 'http', status: response.status });\n}\n\nfunction payloadError(payload, { t = tZh } = {}) {\n  if (!payload?.error) return null;\n  const rawMessage = String(payload.error.message ?? '').replace(/\\s+/g, ' ').slice(0, 180);\n  const kind = /unauthori[sz]ed|forbidden|invalid.?token|invalid.?key|credential|access.?denied|未授权|无权|密钥|令牌/i.test(rawMessage)\n    ? 'auth'\n    : 'protocol';\n  return new McpHttpError(t('MCP 返回错误{detail}', { detail: rawMessage ? `${t('：')}${rawMessage}` : '' }), { kind });\n}\n\nfunction requestHeaders(record, grants, { sessionId, protocolVersion } = {}) {\n  return {\n    'Content-Type': 'application/json',\n    Accept: 'application/json, text/event-stream',\n    ...authHeaders(record, grants),\n    ...(sessionId ? { 'Mcp-Session-Id': sessionId } : {}),\n    ...(protocolVersion ? { 'MCP-Protocol-Version': protocolVersion } : {}),\n  };\n}\n\n// A streamable-HTTP response may stay open after the matching JSON-RPC reply\n// (persistent SSE). Consume complete events until that reply arrives instead of\n// waiting for EOF, and ignore notifications / unrelated request ids.\nasync function readResponsePayload(response, { id, t = tZh } = {}) {\n  const contentType = (response.headers.get('content-type') ?? '').toLowerCase();\n  if (id === undefined || !contentType.includes('text/event-stream')) {\n    const text = await readLimitedText(response, MAX_RESPONSE_BYTES, { t });\n    return { text, payload: parseMcpPayload(text, contentType) };\n  }\n  return readSseResponse(response, {\n    id, maxBytes: MAX_RESPONSE_BYTES, tooLarge: () => new McpHttpError(t('MCP 响应过大')),\n  });\n}\n\nasync function post(record, payload, { grants, sessionId, protocolVersion, signal, fetchImpl, t = tZh }) {\n  const response = await fetchImpl(record.url, {\n    method: 'POST',\n    headers: requestHeaders(record, grants, { sessionId, protocolVersion }),\n    body: JSON.stringify(payload),\n    signal,\n    redirect: 'follow',\n  });\n  const { text, payload: parsed } = await readResponsePayload(response, { id: payload?.id, t });\n  return { response, text, payload: parsed };\n}\n\nasync function closeSession(record, { grants, sessionId, protocolVersion, fetchImpl }) {\n  if (!sessionId) return;\n  try {\n    const response = await fetchImpl(record.url, {\n      method: 'DELETE',\n      headers: requestHeaders(record, grants, { sessionId, protocolVersion }),\n      redirect: 'follow',\n      signal: AbortSignal.timeout(3_000),\n    });\n    await response.body?.cancel().catch(() => {});\n  } catch {}\n}\n\nasync function listMcpToolsOnce(record, {\n  timeoutMs = 15_000,\n  fetchImpl = fetch,\n  grants = new Map(),\n  t = tZh,\n} = {}) {\n  if (record.transport && record.transport !== 'streamable-http') {\n    throw new McpHttpError(t('动态工具加载暂不支持 {transport} 传输', { transport: record.transport }), { kind: 'protocol' });\n  }\n  const controller = new AbortController();\n  const timer = setTimeout(() => controller.abort(new Error('timeout')), timeoutMs);\n  let sessionId = '';\n  let protocolVersion = MCP_PROTOCOL_VERSION;\n  let stage = 'mcp-initialize';\n  let connectionCheckedAt;\n  try {\n    const initialized = await post(record, {\n      jsonrpc: '2.0',\n      id: 1,\n      method: 'initialize',\n      params: {\n        protocolVersion: MCP_PROTOCOL_VERSION,\n        capabilities: {},\n        clientInfo: { name: 'dsh-mcp-connector', version: '1.0' },\n      },\n    }, { grants, signal: controller.signal, fetchImpl, t });\n    if (!initialized.response.ok) throw responseError(initialized.response, initialized.payload, initialized.text, { t });\n    const initPayloadError = payloadError(initialized.payload, { t });\n    if (initPayloadError) throw initPayloadError;\n    if (!initialized.payload?.result || typeof initialized.payload.result !== 'object') {\n      throw new McpHttpError(t('MCP Server 未返回有效的 initialize 结果'));\n    }\n    protocolVersion = initialized.payload.result.protocolVersion || MCP_PROTOCOL_VERSION;\n    sessionId = initialized.response.headers.get('mcp-session-id') ?? '';\n\n    const notification = await post(record, {\n      jsonrpc: '2.0',\n      method: 'notifications/initialized',\n      params: {},\n    }, { grants, sessionId, protocolVersion, signal: controller.signal, fetchImpl, t });\n    if (!notification.response.ok) {\n      throw responseError(notification.response, notification.payload, notification.text, { t });\n    }\n\n    connectionCheckedAt = Date.now();\n    stage = 'tool-discovery';\n    const tools = [];\n    const seenCursors = new Set();\n    let cursor;\n    for (let page = 0; page < MAX_TOOL_PAGES; page += 1) {\n      const listed = await post(record, {\n        jsonrpc: '2.0',\n        id: page + 2,\n        method: 'tools/list',\n        params: cursor ? { cursor } : {},\n      }, { grants, sessionId, protocolVersion, signal: controller.signal, fetchImpl, t });\n      if (!listed.response.ok) throw responseError(listed.response, listed.payload, listed.text, { t });\n      const listPayloadError = payloadError(listed.payload, { t });\n      if (listPayloadError) throw listPayloadError;\n      const pageTools = listed.payload?.result?.tools;\n      if (!Array.isArray(pageTools)) throw new McpHttpError(t('MCP tools/list 未返回工具数组'));\n      tools.push(...pageTools);\n      if (tools.length > MAX_TOOLS) {\n        throw new McpHttpError(t('MCP 工具数量超过安全上限（{maxTools}）', { maxTools: MAX_TOOLS }));\n      }\n\n      const nextCursor = listed.payload?.result?.nextCursor;\n      if (typeof nextCursor !== 'string' || nextCursor.length === 0) {\n        return { tools, protocolVersion, sessionful: Boolean(sessionId), pages: page + 1, connectionCheckedAt };\n      }\n      if (seenCursors.has(nextCursor)) {\n        throw new McpHttpError(t('MCP tools/list 返回了重复分页游标'));\n      }\n      seenCursors.add(nextCursor);\n      cursor = nextCursor;\n    }\n    throw new McpHttpError(t('MCP tools/list 分页超过安全上限（{maxPages} 页）', { maxPages: MAX_TOOL_PAGES }));\n  } catch (error) {\n    // Keep transport errors and their causes intact for retry/error classification.\n    const failure = error instanceof Error ? error : new Error(String(error));\n    failure.stage = stage;\n    failure.connectionCheckedAt = connectionCheckedAt;\n    throw failure;\n  } finally {\n    clearTimeout(timer);\n    await closeSession(record, { grants, sessionId, protocolVersion, fetchImpl });\n  }\n}\n\nfunction errorChain(error) {\n  const parts = [];\n  let current = error;\n  for (let depth = 0; current && depth < 4; depth += 1) {\n    parts.push(current.code, current.name, current.message);\n    current = current.cause;\n  }\n  return parts.filter(Boolean).join(' ');\n}\n\nfunction isRetryableDiscoveryError(error) {\n  if (error instanceof McpHttpError) {\n    return error.kind === 'http' && Number(error.status) >= 500;\n  }\n  const text = errorChain(error);\n  if (/AbortError|timeout|timed out|ETIMEDOUT/i.test(text)) return false;\n  return /ECONNRESET|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|fetch failed|socket disconnected|connection reset|network error/i.test(text);\n}\n\n/**\n * 获取完整工具目录。瞬时网络错误或 5xx 最多自动重试一次；鉴权、协议、\n * 4xx 和超时不会重试，避免掩盖无效凭据或延长确定性失败。\n */\nexport async function listMcpTools(record, options = {}) {\n  const retryCount = Math.max(0, Math.min(Number(options.retryCount ?? 1), 2));\n  const retryDelayMs = Math.max(0, Math.min(Number(options.retryDelayMs ?? 250), 2_000));\n  const requestOptions = { ...options };\n  delete requestOptions.retryCount;\n  delete requestOptions.retryDelayMs;\n\n  for (let attempt = 0; ; attempt += 1) {\n    try {\n      const result = await listMcpToolsOnce(record, requestOptions);\n      return { ...result, attempts: attempt + 1 };\n    } catch (error) {\n      if (attempt >= retryCount || !isRetryableDiscoveryError(error)) throw error;\n      if (retryDelayMs > 0) await new Promise((resolve) => setTimeout(resolve, retryDelayMs));\n    }\n  }\n}\n"
    },
    {
      "path": "lib/mcp-provision.js",
      "content": "/**\n * MCP 条目动态配置：通过 ctx.loader 创建/更新/停用/移除 @deepseek-ai/dsh-mcp-client 条目。\n * entryId = {entryPrefix}-{record.key}；serverName 决定工具名前缀，生命周期内不变 → 幂等。\n */\n\nimport { cliBridgeArgs } from './cli-providers.js';\nimport { effectiveLocalRecord } from './local-overrides.js';\nimport { fileURLToPath } from 'node:url';\n\nconst STDIO_STARTUP_GUARD = fileURLToPath(new URL('./stdio-startup-guard.js', import.meta.url));\n\n/**\n * 桌面宿主（Electron 内嵌 DSH）的 `process.execPath` 是可执行文件本体：只有带上\n * `ELECTRON_RUN_AS_NODE` 才会作为 Node 运行 guard 脚本；CLI 宿主（node 进程）不需要。\n * 该变量只服务于 guard 自身，guard 启动真实 server 前会把它移除。\n */\nfunction isElectronRuntime() {\n  return typeof process.versions?.electron === 'string';\n}\n\nexport function entryIdFor(config, record) {\n  return `${config.entryPrefix}-${record.key}`;\n}\n\n/** 由连接记录 + grant 集合构造条目 headers（含鉴权头） */\nexport function authHeaders(record, grants) {\n  const headers = { ...(record.headers ?? {}) };\n  if (!record.auth) return headers;\n  if (record.auth.mode === 'oauth') {\n    const grant = record.auth.grantKey ? grants.get(record.auth.grantKey) : null;\n    if (grant?.accessToken) headers.Authorization = `Bearer ${grant.accessToken}`;\n  } else if (record.auth.mode === 'bearer') {\n    if (record.auth.bearerToken) headers.Authorization = `Bearer ${record.auth.bearerToken}`;\n  } else if (record.auth.mode === 'api-key') {\n    if (record.auth.apiKeyHeader && record.auth.apiKeyValue !== undefined && record.auth.apiKeyValue !== '') {\n      headers[record.auth.apiKeyHeader] = record.auth.apiKeyValue;\n    }\n  }\n  return headers;\n}\n\nexport function buildEntryConfig(record, grants, { failOnStartupError = false, startupRequestTimeoutMs } = {}) {\n  record = effectiveLocalRecord(record);\n  if (record.transport === 'stdio') {\n    const env = { ...(record.env ?? {}) };\n    if (record.auth?.mode === 'oauth' && record.oauthTokenEnv) {\n      const grant = record.auth.grantKey ? grants.get(record.auth.grantKey) : null;\n      if (grant?.accessToken) env[record.oauthTokenEnv] = `Bearer ${grant.accessToken}`;\n    }\n    const guarded = startupRequestTimeoutMs !== undefined;\n    if (guarded && (!Number.isSafeInteger(startupRequestTimeoutMs) || startupRequestTimeoutMs < 100 || startupRequestTimeoutMs > 2_147_483_647)) {\n      throw new RangeError('stdio startup request timeout must be an integer between 100 and 2147483647 ms');\n    }\n    const args = cliBridgeArgs(record);\n    return {\n      transport: 'stdio',\n      serverName: record.serverName,\n      command: guarded ? process.execPath : record.command,\n      args: guarded ? [STDIO_STARTUP_GUARD, '--timeout-ms', String(startupRequestTimeoutMs), '--', record.command, ...args] : args,\n      env: guarded && isElectronRuntime() ? { ...env, ELECTRON_RUN_AS_NODE: '1' } : env,\n      cwd: record.cwd || process.cwd(),\n      failOnStartupError,\n    };\n  }\n  return {\n    transport: 'streamable-http',\n    serverName: record.serverName,\n    url: record.url,\n    headers: authHeaders(record, grants),\n    failOnStartupError,\n  };\n}\n\nfunction hasEntry(ctx, id) {\n  try {\n    ctx.loader.resolve(id);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/** 创建或更新一条 mcp-client 条目（幂等；serverName 不变则工具名不变） */\nexport async function provision(ctx, config, record, grants, { failOnStartupError = false, startupRequestTimeoutMs } = {}) {\n  const id = entryIdFor(config, record);\n  const entryConfig = buildEntryConfig(record, grants, { failOnStartupError, startupRequestTimeoutMs });\n  const disabled = record.enabled === false;\n  if (hasEntry(ctx, id)) {\n    const existing = ctx.loader.resolve(id);\n    const previous = existing?.options?.config ?? {};\n    const nextConfig = previous.transport && previous.transport !== entryConfig.transport\n      ? entryConfig\n      : { ...previous, ...entryConfig };\n    await ctx.loader.update(id, { config: nextConfig, disabled });\n  } else {\n    await ctx.loader.create({ id, name: '@deepseek-ai/dsh-mcp-client', config: entryConfig, disabled });\n  }\n  return id;\n}\n\n/** 停用（保留记录，可重新启用） */\nexport async function disable(ctx, config, record) {\n  const id = entryIdFor(config, record);\n  if (hasEntry(ctx, id)) await ctx.loader.update(id, { disabled: true });\n  return id;\n}\n\n/** 移除条目 */\nexport async function remove(ctx, config, record) {\n  const id = entryIdFor(config, record);\n  if (hasEntry(ctx, id)) await ctx.loader.remove(id);\n  return id;\n}\n\n/** 按 serverName 判重（幂等 upsert 用） */\nexport function dedupeByServerName(records) {\n  const seen = new Map();\n  for (const record of records) {\n    if (seen.has(record.serverName)) continue;\n    seen.set(record.serverName, record);\n  }\n  return [...seen.values()];\n}\n"
    },
    {
      "path": "lib/mcp-sse.js",
      "content": "/** Read the first complete SSE event matching a JSON-RPC request, without waiting for EOF. */\nexport async function readSseResponse(response, { id, maxBytes, tooLarge }) {\n  if (!response.body) return { text: '', payload: undefined };\n  const reader = response.body.getReader();\n  const decoder = new TextDecoder();\n  let line = '';\n  let data = [];\n  let skipLF = false;\n  let total = 0;\n  try {\n    for (;;) {\n      const { done, value } = await reader.read();\n      // EOF does not dispatch an event lacking its final blank line.\n      if (done) return { text: '', payload: undefined };\n      total += value.byteLength;\n      if (total > maxBytes) throw tooLarge();\n      const text = decoder.decode(value, { stream: true });\n      if (!text) continue;\n      let start = skipLF && text.startsWith('\\n') ? 1 : 0;\n      skipLF = text.endsWith('\\r');\n      const endings = /\\r\\n|\\r|\\n/g;\n      endings.lastIndex = start;\n      let ending;\n      while ((ending = endings.exec(text))) {\n        line += text.slice(start, ending.index);\n        start = endings.lastIndex;\n        if (line === '') {\n          const event = data.join('\\n');\n          data = [];\n          let payload;\n          try { payload = JSON.parse(event); } catch { continue; }\n          if (payload?.jsonrpc === '2.0' && payload.id === id && ('result' in payload || 'error' in payload)) {\n            return { text: event, payload };\n          }\n        } else {\n          if (line === 'data') data.push('');\n          else if (line.startsWith('data:')) data.push(line.slice(5).replace(/^ /, ''));\n          line = '';\n        }\n      }\n      line += text.slice(start);\n    }\n  } finally {\n    // A server or stream adapter may never resolve cancellation; do not await it.\n    void reader.cancel().catch(() => {});\n    reader.releaseLock();\n  }\n}\n"
    },
    {
      "path": "lib/session-injection.js",
      "content": "/**\n * Per-Agent MCP tool visibility.\n *\n * Connections remain provisioned; this controller only narrows the Host tool\n * view and dispatch boundary for records explicitly configured as `session`.\n * State is memory-only and keyed by the live Agent object, so it cannot leak to\n * another conversation or survive a DSH restart.\n */\n\nimport { DEFAULT_LOCALE, createTranslator } from './i18n/index.js';\n\n/** 缺省译文：中文（既有调用点与测试无需改动）。 */\nconst tZh = createTranslator(DEFAULT_LOCALE);\nimport { readHostToolNames, supportsHostToolNames } from './host-tool-names.js';\n\nexport const INJECTION_MODES = ['always', 'session'];\nexport const DEFAULT_SESSION_TOOL_TTL_MINUTES = 30;\nexport const MAX_SESSION_TOOL_TTL_MINUTES = 30;\n\n/** 枚举值（`always` / `session`）本身不翻译，只翻译错误文案。 */\nexport function normalizeInjectionMode(value, { t = tZh } = {}) {\n  if (value === undefined || value === null || value === '') return 'always';\n  if (!INJECTION_MODES.includes(value)) throw new Error(t('不支持的工具注入模式: {value}', { value }));\n  return value;\n}\n\nfunction normalizeTtlMinutes(value, { t = tZh } = {}) {\n  if (value === undefined || value === null) return DEFAULT_SESSION_TOOL_TTL_MINUTES;\n  const ttl = Number(value);\n  if (!Number.isFinite(ttl) || ttl < 1 || ttl > MAX_SESSION_TOOL_TTL_MINUTES) {\n    throw new Error(t('ttlMinutes 必须介于 1 与 {max} 之间', { max: MAX_SESSION_TOOL_TTL_MINUTES }));\n  }\n  return ttl;\n}\n\nfunction uniqueNames(values) {\n  return [...new Set((Array.isArray(values) ? values : [])\n    .filter((value) => typeof value === 'string' && value.trim())\n    .map((value) => value.trim()))].sort();\n}\n\nfunction sameNames(left, right) {\n  return left.length === right.length && left.every((name, index) => name === right[index]);\n}\n\nfunction agentLabel(agent) {\n  return String(agent?.id ?? 'unknown');\n}\n\n/** Host-enforced, memory-only session visibility for MCP business tools. */\nexport function createSessionToolInjectionController(ctx, {\n  getRecords,\n  workspaceIdForAgent,\n  isRecordVisible = () => true,\n  isToolAllowed = () => true,\n  now = () => Date.now(),\n  logger,\n  t = tZh,\n} = {}) {\n  let disposed = false;\n  let agentsMounted = false;\n  let mountedAgentCtx = null;\n  let agentMountDispose = null;\n  let expiryTimer = null;\n  let syncing = false;\n  const restrictions = new Map();\n  const states = new Map();\n\n  const records = () => [...(getRecords?.() ?? [])];\n\n  function recordForPublicName(name) {\n    if (typeof name !== 'string' || !name.startsWith('mcp__')) return null;\n    return records()\n      .filter((record) => name.startsWith(`mcp__${record.serverName}__`))\n      .sort((a, b) => b.serverName.length - a.serverName.length)[0] ?? null;\n  }\n\n  function observedPublicNames() {\n    try {\n      return readHostToolNames(ctx.tools, { t })\n        .filter((name) => typeof name === 'string' && recordForPublicName(name))\n        .sort();\n    } catch (error) {\n      logger?.warn?.(`session injection read Host tools failed: ${error.message}`);\n      return null;\n    }\n  }\n\n  function stateFor(agent, create = false) {\n    let state = states.get(agent);\n    if (!state && create) {\n      state = { revision: 0, activations: new Map() };\n      states.set(agent, state);\n    }\n    return state;\n  }\n\n  function activationValid(agent, publicName, at = now()) {\n    const activation = stateFor(agent)?.activations.get(publicName);\n    return Boolean(activation && activation.expiresAt > at);\n  }\n\n  function purgeState(agent, observedSet, at = now()) {\n    const state = stateFor(agent);\n    if (!state) return false;\n    let changed = false;\n    for (const [publicName, activation] of state.activations) {\n      const record = recordForPublicName(publicName);\n      if (activation.expiresAt <= at\n          || (observedSet && !observedSet.has(publicName))\n          || !record\n          || record.key !== activation.connectionKey\n          || record.enabled === false\n          || normalizeInjectionMode(record.injectionMode, { t }) !== 'session') {\n        state.activations.delete(publicName);\n        changed = true;\n      }\n    }\n    if (changed) state.revision += 1;\n    if (state.activations.size === 0 && state.revision === 0) states.delete(agent);\n    return changed;\n  }\n\n  function scheduleExpiry() {\n    clearTimeout(expiryTimer);\n    expiryTimer = null;\n    if (disposed) return;\n    let nextExpiry = Number.POSITIVE_INFINITY;\n    for (const state of states.values()) {\n      for (const activation of state.activations.values()) nextExpiry = Math.min(nextExpiry, activation.expiresAt);\n    }\n    if (!Number.isFinite(nextExpiry)) return;\n    expiryTimer = setTimeout(() => {\n      expiryTimer = null;\n      refresh();\n    }, Math.max(0, nextExpiry - now()) + 1);\n    expiryTimer.unref?.();\n  }\n\n  function deniedNames(agent, observed) {\n    const at = now();\n    return observed.filter((name) => {\n      const record = recordForPublicName(name);\n      return record\n        && record.enabled !== false\n        && normalizeInjectionMode(record.injectionMode, { t }) === 'session'\n        && !activationValid(agent, name, at);\n    });\n  }\n\n  function installRestriction(agent, denied) {\n    const current = restrictions.get(agent);\n    if (current && sameNames(current.denied, denied)) return;\n    if (denied.length === 0) {\n      current?.dispose?.();\n      restrictions.delete(agent);\n      return;\n    }\n    try {\n      // Install the new, equally-or-more-current restriction before releasing\n      // the prior layer. This keeps schema/lookup/dispatch fail closed while\n      // tools/change is racing with an activation update.\n      const dispose = agent.ctx.tools.restrict({ deny: denied });\n      restrictions.set(agent, { denied, dispose });\n      current?.dispose?.();\n    } catch (error) {\n      logger?.warn?.(`session injection restrict agent \"${agentLabel(agent)}\" failed: ${error.message}`);\n    }\n  }\n\n  function refresh() {\n    if (disposed || !agentsMounted || syncing) return;\n    syncing = true;\n    try {\n      const live = new Set(mountedAgentCtx?.agents?.list?.() ?? []);\n      // Legacy/default always-on connections need no session visibility mask.\n      // Still reconcile empty masks and purge activations when the mode changes.\n      const needsRestriction = records().some((record) => (\n        record.enabled !== false && normalizeInjectionMode(record.injectionMode) === 'session'\n      ));\n      const observed = live.size && needsRestriction ? observedPublicNames() : [];\n      if (observed === null) return;\n      const observedSet = new Set(observed);\n      for (const agent of live) {\n        purgeState(agent, observedSet);\n        installRestriction(agent, deniedNames(agent, observed));\n      }\n      for (const agent of [...restrictions.keys()]) {\n        if (!live.has(agent)) {\n          restrictions.get(agent)?.dispose?.();\n          restrictions.delete(agent);\n        }\n      }\n      for (const agent of [...states.keys()]) if (!live.has(agent)) states.delete(agent);\n      scheduleExpiry();\n    } finally {\n      syncing = false;\n    }\n  }\n\n  const disposeGuard = typeof ctx.tools?.guard === 'function'\n    ? ctx.tools.guard((execution) => {\n        const record = recordForPublicName(execution.name);\n        if (!record || normalizeInjectionMode(record.injectionMode, { t }) !== 'session') return undefined;\n        if (record.enabled === false) return t('MCP 工具 {name} 所属连接已停用', { name: execution.name });\n        if (!execution.agent) return t('MCP 工具 {name} 需要当前会话显式激活', { name: execution.name });\n        if (!isRecordVisible(record, execution.agent)) return t('MCP 工具 {name} 不属于当前工作区', { name: execution.name });\n        if (!isToolAllowed(execution.name, record)) return t('MCP 工具 {name} 已被治理策略拒绝', { name: execution.name });\n        if (!activationValid(execution.agent, execution.name)) return t('MCP 工具 {name} 未在当前会话激活或已过期', { name: execution.name });\n        return undefined;\n      })\n    : null;\n\n  function assertSessionCapabilities() {\n    const current = capabilities();\n    if (!current.executionGuard || !current.visibilityRestriction) {\n      throw new Error(t('当前 DSH Host 不同时支持 tools.guard 与 Agent tools.restrict，不能安全使用按会话注入'));\n    }\n  }\n\n  function assertAgent(agent) {\n    if (!agent) throw new Error(t('缺少 Agent 会话上下文'));\n  }\n\n  function activationPlan(agent, input = {}) {\n    assertAgent(agent);\n    assertSessionCapabilities();\n    const connectionKey = typeof input.connectionKey === 'string' ? input.connectionKey.trim() : '';\n    if (!connectionKey) throw new Error(t('connectionKey 必填'));\n    const record = records().find((candidate) => candidate.key === connectionKey);\n    if (!record) throw new Error(t('连接 \"{key}\" 不存在', { key: connectionKey }));\n    if (record.enabled === false) throw new Error(t('连接 \"{name}\" 已停用', { name: record.name }));\n    if (normalizeInjectionMode(record.injectionMode, { t }) !== 'session') {\n      throw new Error(t('连接 \"{name}\" 未设为“按会话启用”', { name: record.name }));\n    }\n    if (!isRecordVisible(record, agent)) throw new Error(t('连接 \"{name}\" 不属于当前工作区', { name: record.name }));\n    const requested = uniqueNames(input.publicNames);\n    if (requested.length === 0) throw new Error(t('必须指定至少一个精确 public tool name'));\n    const names = observedPublicNames();\n    if (names === null) throw new Error(t('Host 工具名称读取失败，暂不能激活工具'));\n    const observed = new Set(names);\n    for (const publicName of requested) {\n      if (!observed.has(publicName)) throw new Error(t('Host 尚未观察到工具 \"{name}\"', { name: publicName }));\n      const owner = recordForPublicName(publicName);\n      if (!owner || owner.key !== record.key) throw new Error(t('工具 \"{tool}\" 不属于连接 \"{name}\"', { tool: publicName, name: record.name }));\n      if (!isToolAllowed(publicName, record)) throw new Error(t('工具 \"{tool}\" 已被治理策略拒绝', { tool: publicName }));\n    }\n    const ttlMinutes = normalizeTtlMinutes(input.ttlMinutes, { t });\n    const state = stateFor(agent);\n    return {\n      baseRevision: state?.revision ?? 0,\n      connectionKey: record.key,\n      connectionName: record.name,\n      serverName: record.serverName,\n      publicNames: requested,\n      newPublicNames: requested.filter((name) => !activationValid(agent, name)),\n      ttlMinutes,\n      expiresAt: now() + ttlMinutes * 60_000,\n      risk: 'unclassified',\n      requiresConfirmation: true,\n      nextInferenceBoundary: true,\n    };\n  }\n\n  function status(agent) {\n    assertAgent(agent);\n    const names = observedPublicNames();\n    if (names === null) throw new Error(t(\"Host 工具名称读取失败，暂不能读取会话工具状态\"));\n    const observed = new Set(names);\n    purgeState(agent, observed);\n    const state = stateFor(agent);\n    const active = [...(state?.activations ?? new Map()).entries()].map(([publicName, activation]) => ({\n      publicName,\n      connectionKey: activation.connectionKey,\n      source: activation.source,\n      activatedAt: activation.activatedAt,\n      expiresAt: activation.expiresAt,\n    })).sort((a, b) => a.publicName.localeCompare(b.publicName));\n    const hiddenCount = deniedNames(agent, [...observed]).length;\n    scheduleExpiry();\n    return {\n      agentId: agentLabel(agent),\n      workspaceId: workspaceIdForAgent?.(agent) ?? null,\n      revision: state?.revision ?? 0,\n      active,\n      activeCount: active.length,\n      hiddenCount,\n      capabilities: capabilities(),\n      persisted: false,\n    };\n  }\n\n  function previewActivation(agent, input) {\n    return activationPlan(agent, input);\n  }\n\n  function activate(agent, input = {}) {\n    if (input.confirmed !== true) throw new Error(t('激活必须来自用户明确确认'));\n    const plan = activationPlan(agent, input);\n    const state = stateFor(agent, true);\n    if (!Number.isInteger(input.expectedRevision) || input.expectedRevision !== state.revision) {\n      throw new Error(t('会话工具状态已变化（当前 revision={revision}），请重新预览', { revision: state.revision }));\n    }\n    const activatedAt = now();\n    const expiresAt = activatedAt + plan.ttlMinutes * 60_000;\n    for (const publicName of plan.publicNames) {\n      state.activations.set(publicName, {\n        connectionKey: plan.connectionKey,\n        source: 'user-confirmed',\n        activatedAt,\n        expiresAt,\n      });\n    }\n    state.revision += 1;\n    refresh();\n    return { ...status(agent), activated: plan.publicNames, nextInferenceBoundary: true };\n  }\n\n  function deactivate(agent, input = {}) {\n    assertAgent(agent);\n    const state = stateFor(agent, true);\n    if (!Number.isInteger(input.expectedRevision) || input.expectedRevision !== state.revision) {\n      throw new Error(t('会话工具状态已变化（当前 revision={revision}），请重新读取', { revision: state.revision }));\n    }\n    const requested = uniqueNames(input.publicNames);\n    const connectionKey = typeof input.connectionKey === 'string' ? input.connectionKey.trim() : '';\n    let changed = false;\n    for (const [publicName, activation] of [...state.activations]) {\n      const remove = requested.length > 0\n        ? requested.includes(publicName)\n        : connectionKey ? activation.connectionKey === connectionKey : true;\n      if (remove) {\n        state.activations.delete(publicName);\n        changed = true;\n      }\n    }\n    if (changed) state.revision += 1;\n    refresh();\n    return { ...status(agent), changed };\n  }\n\n  function forgetConnection(connectionKey) {\n    let changed = false;\n    for (const state of states.values()) {\n      let stateChanged = false;\n      for (const [publicName, activation] of [...state.activations]) {\n        if (activation.connectionKey === connectionKey) {\n          state.activations.delete(publicName);\n          stateChanged = true;\n        }\n      }\n      if (stateChanged) {\n        state.revision += 1;\n        changed = true;\n      }\n    }\n    if (changed) refresh();\n    return changed;\n  }\n\n  function disposeAgent(agent) {\n    restrictions.get(agent)?.dispose?.();\n    restrictions.delete(agent);\n    states.delete(agent);\n    scheduleExpiry();\n  }\n\n  function mountAgents(agentCtx) {\n    agentMountDispose?.();\n    agentsMounted = true;\n    mountedAgentCtx = agentCtx;\n    const stopCreated = agentCtx.on?.('agent/created', refresh);\n    const stopDisposed = agentCtx.on?.('agent/disposed', ({ agent }) => disposeAgent(agent));\n    const stopToolsChange = agentCtx.on?.('tools/change', refresh);\n    refresh();\n    agentMountDispose = () => {\n      agentsMounted = false;\n      mountedAgentCtx = null;\n      stopCreated?.();\n      stopDisposed?.();\n      stopToolsChange?.();\n      for (const entry of restrictions.values()) entry.dispose?.();\n      restrictions.clear();\n      states.clear();\n      clearTimeout(expiryTimer);\n      expiryTimer = null;\n      agentMountDispose = null;\n    };\n    return agentMountDispose;\n  }\n\n  function capabilities() {\n    return {\n      executionGuard: Boolean(disposeGuard),\n      visibilityRestriction: agentsMounted && typeof ctx.tools?.restrict === 'function' && supportsHostToolNames(ctx.tools),\n      activeAgents: mountedAgentCtx?.agents?.list?.().length ?? 0,\n      restrictedAgents: restrictions.size,\n      maxTtlMinutes: MAX_SESSION_TOOL_TTL_MINUTES,\n      statePersistence: 'memory-only',\n    };\n  }\n\n  return {\n    refresh,\n    mountAgents,\n    capabilities,\n    status,\n    previewActivation,\n    activate,\n    deactivate,\n    forgetConnection,\n    inspect(name, agent) {\n      const record = recordForPublicName(name);\n      if (!record) return null;\n      return {\n        record,\n        injectionMode: normalizeInjectionMode(record.injectionMode, { t }),\n        active: Boolean(agent && activationValid(agent, name)),\n      };\n    },\n    dispose() {\n      if (disposed) return;\n      disposed = true;\n      agentMountDispose?.();\n      clearTimeout(expiryTimer);\n      disposeGuard?.();\n    },\n  };\n}\n"
    },
    {
      "path": "lib/tools.js",
      "content": "/**\n * 对话工具面：目录 / 连接 / 配置 / 导入 / 安全编辑 / 脱敏导出 / 快照 / URL 安装 / 状态 / 启停 / 断开 / 刷新目录 / 上下架。\n */\nimport { DEFAULT_LOCALE, createTranslator } from './i18n/index.js';\n\nconst RESULT_SCHEMA = {\n  type: 'object',\n  properties: {\n    ok: { type: 'boolean' },\n    message: { type: 'string' },\n    detail: { type: 'object', additionalProperties: true },\n  },\n  required: ['ok', 'message'],\n  additionalProperties: true,\n};\n\nconst resultOutput = {\n  schema: RESULT_SCHEMA,\n  render(args, value) {\n    return [{ type: 'text', text: value.message }];\n  },\n};\n\nconst exportOutput = {\n  schema: RESULT_SCHEMA,\n  render(args, value) {\n    const json = value.ok ? value.detail?.json : '';\n    return [{ type: 'text', text: json ? `${value.message}\\n\\n\\`\\`\\`json\\n${json}\\n\\`\\`\\`` : value.message }];\n  },\n};\n\n/**\n * 渲染器都是 `t` 的工厂：工具定义在 `registerTools()` 内按当前语言构建，\n * 这样同一份 schema 在不同语言下连渲染连接词也一致。\n */\nconst snapshotOutput = (t) => ({\n  schema: RESULT_SCHEMA,\n  render(args, value) {\n    const lines = [value.message];\n    for (const item of value.detail?.items ?? []) {\n      lines.push(`- [${item.id}] ${new Date(item.createdAt).toISOString()} · ${item.reason} · ${t('{count} 条', { count: item.existingCount })}${item.restorable ? '' : t(' · 需重新授权')}`);\n    }\n    return [{ type: 'text', text: lines.join('\\n') }];\n  },\n});\n\nfunction diagnosticText(t, diagnostic) {\n  const checkedAt = Number.isFinite(diagnostic.checkedAt) ? t('；检查时间：{time}', { time: new Date(diagnostic.checkedAt).toISOString() }) : '';\n  const lastSuccessfulAt = Number.isFinite(diagnostic.lastSuccessfulAt) ? t('；最近成功：{time}', { time: new Date(diagnostic.lastSuccessfulAt).toISOString() }) : '';\n  return `${diagnostic.stageLabel || diagnostic.stage} / ${diagnostic.code} · ${diagnostic.message}${t('；建议：{action}', { action: diagnostic.action })}${checkedAt}${lastSuccessfulAt}`;\n}\n\n/** 目录工具：把货架明细逐条渲染出来，模型才能读到名称/分类/鉴权方式 */\nconst catalogOutput = (t) => ({\n  schema: RESULT_SCHEMA,\n  render(args, value) {\n    const lines = [value.message];\n    const items = value.detail?.items ?? [];\n    if (items.length) {\n      lines.push('');\n      for (const it of items) {\n        const star = it.featured ? '⭐ ' : '';\n        const connected = it.connected?.length\n          ? t('（{label} {count}）', { label: it.connectionLabel || t('已配置'), count: it.connected.length })\n          : '';\n        const summary = it.summary ? ` — ${it.summary}` : '';\n        lines.push(`- ${star}[${it.id}] ${it.name} · ${it.category} · ${it.authMode}${connected}${summary}`);\n      }\n    }\n    return [{ type: 'text', text: lines.join('\\n') }];\n  },\n});\n\n/** 状态工具：把每条连接逐条渲染出来 */\nconst statusOutput = (t) => ({\n  schema: RESULT_SCHEMA,\n  render(args, value) {\n    const lines = [value.message];\n    const items = value.detail?.items ?? [];\n    if (items.length) {\n      lines.push('');\n      for (const it of items) {\n        const stateLabels = { healthy: t('已连接'), unknown: t('状态未知'), configured: t('已配置'), reauth: t('需重新授权'), recovering: t('自动重试中'), degraded: t('部分异常'), unavailable: t('连接异常'), disabled: t('已停用') };\n        const state = it.enabled ? (stateLabels[it.connectionState] || t('状态未知')) : t('停用');\n        const auth = it.authMode === 'oauth'\n          ? it.grant?.needsReauth ? `oauth${t('(需重新授权)')}` : it.grant?.missing ? `oauth${t('(授权缺失)')}` : 'oauth'\n          : it.authMode;\n        const injection = it.injectionMode === 'session' ? t('按会话启用') : t('始终注入');\n        lines.push(`- [${it.key}] ${it.name} (${it.serverName}) · ${it.kind}/${auth}/${it.transport} · ${state} · ${injection} · ${it.scope?.label || t('全局')} → ${it.endpoint || it.url || ''}`);\n        if (it.diagnostic) {\n          lines.push(`  ${t('诊断：{diagnostic}', { diagnostic: diagnosticText(t, it.diagnostic) })}`);\n        }\n      }\n    }\n    return [{ type: 'text', text: lines.join('\\n') }];\n  },\n});\n\n/** 健康检查工具：逐连接器渲染状态、失败阶段与建议动作。 */\nconst healthOutput = (t) => ({\n  schema: RESULT_SCHEMA,\n  render(args, value) {\n    const lines = [value.message];\n    for (const item of value.detail?.items ?? []) {\n      lines.push(`- [${item.connectorId}] ${item.label} · ${t('{available}/{enabled} 个 Server 可用', { available: item.availableServers, enabled: item.enabledServers })}`);\n      if (item.diagnostic) {\n        lines.push(`  ${t('诊断：{diagnostic}', { diagnostic: diagnosticText(t, item.diagnostic) })}`);\n      }\n    }\n    return [{ type: 'text', text: lines.join('\\n') }];\n  },\n});\n\nconst governanceOutput = (t) => ({\n  schema: RESULT_SCHEMA,\n  render(args, value) {\n    const lines = [value.message];\n    for (const rule of value.detail?.rules ?? []) {\n      const target = rule.scope === 'connection'\n        ? rule.connectorId\n        : rule.scope === 'server'\n          ? `${rule.connectorId}/${rule.serverName}`\n          : `${rule.connectorId}/${rule.serverName}/${rule.toolName}`;\n      lines.push(`- ${rule.scope} · ${target} · ${rule.effect} · ${rule.statusLabel || rule.status}`);\n    }\n    return [{ type: 'text', text: lines.join('\\n') }];\n  },\n});\n\nconst sessionToolsOutput = (t) => ({\n  schema: RESULT_SCHEMA,\n  render(args, value) {\n    const lines = [value.message];\n    for (const item of value.detail?.items ?? []) {\n      const publicName = item.publicName ? ` → ${item.publicName}` : '';\n      lines.push(`- [${item.connectionKey}] ${item.serverName}/${item.name}${publicName}`);\n    }\n    for (const item of value.detail?.active ?? value.detail?.session?.active ?? []) {\n      lines.push(`- ${t('已激活 {name} · 到期 {time}', { name: item.publicName, time: new Date(item.expiresAt).toISOString() })}`);\n    }\n    if (value.ok && args.action === 'search') {\n      lines.push(t('下一步：选择同一 connectionKey 下的精确 publicName，调用 preview-activate；不要猜测名称。没有结果时检查连接与工具发现，不要重复空搜索。'));\n    }\n    if (value.ok && args.action === 'preview-activate' && Number.isInteger(value.detail?.baseRevision)) {\n      const plan = value.detail;\n      lines.push(t('预览不会激活工具。向用户展示以下精确工具并等待明确确认；只有确认后才能把 confirmed 改为 true。不要重复预览或把预览成功当作用户确认。'));\n      lines.push(JSON.stringify({ action: 'activate', connectionKey: plan.connectionKey,\n        publicNames: plan.publicNames, ttlMinutes: plan.ttlMinutes,\n        expectedRevision: plan.baseRevision, confirmed: false }));\n    }\n    if (value.ok && args.action === 'activate') {\n      lines.push(t('激活已完成，不要再次 search、preview-activate 或 activate。下一次推理使用返回的精确工具；若仍不可见，读取一次 status 后报告问题，不要循环激活。'));\n      for (const name of value.detail?.activated ?? []) lines.push(`- ${name}`);\n    }\n    if (Number.isInteger(value.detail?.revision)) lines.push(`revision=${value.detail.revision}`);\n    if (!value.ok) lines.push(t('本次操作失败。先根据错误修正参数或检查 Host；不要原样重复调用，不得绕过用户确认、工作区或治理限制。'));\n    if (value.detail?.nextInferenceBoundary) lines.push(t('可见性从下一次模型推理边界生效。'));\n    return [{ type: 'text', text: lines.join('\\n') }];\n  },\n});\n\nconst noArgs = { type: 'object', properties: {}, additionalProperties: false };\n\n/**\n * DSH tools require a lossless JSON value at the execute boundary. Normalize\n * values that JSON.stringify would otherwise drop or rewrite, and always emit\n * plain objects so transport-specific undefined fields cannot reject a tool\n * result on stricter Desktop hosts.\n */\nexport function toLossless(value, seen = new Set()) {\n  if (value === null) return null;\n  const type = typeof value;\n  if (type === 'string' || type === 'boolean') return value;\n  if (type === 'number') {\n    if (!Number.isFinite(value)) return null;\n    return Object.is(value, -0) ? 0 : value;\n  }\n  if (type === 'undefined' || type === 'function' || type === 'symbol' || type === 'bigint') return null;\n  if (type !== 'object' || seen.has(value)) return null;\n\n  seen.add(value);\n  let output;\n  if (Array.isArray(value)) {\n    output = [];\n    for (let index = 0; index < value.length; index += 1) {\n      output[index] = Object.hasOwn(value, index) ? toLossless(value[index], seen) : null;\n    }\n  } else {\n    output = {};\n    for (const key of Object.keys(value)) output[key] = toLossless(value[key], seen);\n  }\n  seen.delete(value);\n  return output;\n}\n\n/**\n * 注册对话工具。\n *\n * `t` 默认是中文 translator，因此既有调用点（含测试）不传 `t` 也保持原有中文文案。\n */\nexport function registerTools(ctx, api, { compact = false, t = createTranslator(DEFAULT_LOCALE) } = {}) {\n  const definitions = [];\n  const reg = (def) => definitions.push({\n    ...def,\n    async execute(args, exec) {\n      return toLossless(await def.execute(args, exec));\n    },\n  });\n\n  reg({\n    name: 'mcp_connector_catalog',\n    description: t('列出 MCP 连接器市场目录（货架）：已上架的连接器，含名称/厂商/简介/分类/标签，以及是否已连接。可按分类或关键词过滤。用户说「列出连接器」「有哪些连接器」「连接器市场」时使用。'),\n    parameters: {\n      type: 'object',\n      properties: {\n        category: { type: 'string', description: t('按分类过滤（企业数据/办公协作/地图出行/金融行情/开发工具/数据库/AI 模型/其他）') },\n        keyword: { type: 'string', description: t('按名称/厂商/简介/标签关键词过滤') },\n        workspaceId: { type: 'string', description: t('可选；按指定 Workspace 计算已连接状态') },\n      },\n      additionalProperties: false,\n    },\n    output: catalogOutput(t),\n    async execute(args) {\n      return api.catalog(args ?? {});\n    },\n  });\n\n  reg({\n    name: 'mcp_connector_connect',\n    description: t('一键连接某个 MCP 连接器（按 connectorId）。OAuth 型会打开系统浏览器跳转授权页，登录授权后自动完成；无鉴权型直接连接；需要 API Key / Bearer Token 的会提示改用 mcp_connector_configure 填写凭据。'),\n    parameters: {\n      type: 'object',\n      properties: {\n        connectorId: { type: 'string', description: t('连接器 id（来自 mcp_connector_catalog）') },\n        serverKey: { type: 'string', description: t('多 server 连接器指定入口 serverKey（可选）') },\n        scope: { type: 'string', enum: ['global', 'project'], description: t('目标作用域；新连接省略时使用 global，已有连接重新授权时保留原范围') },\n        workspaceId: { type: 'string', description: t('scope=project 时必填，来自 mcp_connector_scope context') },\n      },\n      required: ['connectorId'],\n      additionalProperties: false,\n    },\n    output: resultOutput,\n    timeoutMs: 180_000,\n    async execute(args, exec) {\n      return api.connect(args.connectorId, args.serverKey, exec.signal, args);\n    },\n  });\n\n  reg({\n    name: 'mcp_connector_configure',\n    description: t('自定义配置一个外部 MCP Server 连接：HTTP 可填写 URL/鉴权；stdio 可填写 command/args/env/cwd。也可对市场中的 Bearer/API Key 连接器按 connectorId 一次配置全部 Server；stdio 凭据会按目录声明安全注入本机环境变量。参数三选一：市场连接器提供 connectorId；自定义 HTTP 提供 name 和 url；自定义 stdio 提供 name、transport=stdio 和 command。市场连接器会先验证或交由 Host 托管，通过后才保存。'),\n    parameters: {\n      type: 'object',\n      properties: {\n        connectorId: { type: 'string', description: t('市场凭据型连接器 id；提供时无需 name/url') },\n        name: { type: 'string', description: t('连接展示名') },\n        url: { type: 'string', description: t('MCP 端点 URL（https 或回环 http；私有 IP 的 http 需显式授权）') },\n        allowInsecurePrivateNetwork: {\n          type: 'boolean',\n          description:  t('仅用于用户自建连接：显式授权 RFC1918 IPv4 / RFC4193 IPv6 ULA 字面量使用明文 HTTP；公网 HTTP 与域名仍拒绝'),\n        },\n        transport: { type: 'string', enum: ['streamable-http', 'stdio', 'sse'], description: t('传输方式；sse 会兼容归一为 streamable-http') },\n        command: { type: 'string', description: t('transport=stdio 时的启动命令（如 npx、uvx）') },\n        args: { type: 'array', items: { type: 'string' }, description: t('transport=stdio 时的参数列表') },\n        envJson: { type: 'string', description: t('transport=stdio 时的环境变量 JSON；可能含凭据，仅保存在本机') },\n        cwd: { type: 'string', description: t('transport=stdio 时的工作目录；默认 DSH 当前目录') },\n        serverName: { type: 'string', description: t('serverName（决定工具名前缀 mcp__<serverName>__*，默认由 name 归一）') },\n        authMode: { type: 'string', enum: ['none', 'bearer', 'api-key'], description: t('鉴权方式，默认 none') },\n        bearerToken: { type: 'string', description: t('authMode=bearer 时的 token') },\n        apiKeyHeader: { type: 'string', description: t('authMode=api-key 时的头名，默认 X-Api-Key') },\n        apiKeyValue: { type: 'string', description: t('authMode=api-key 时的值') },\n        credentialValues: {\n          type: 'object',\n          additionalProperties: { type: 'string' },\n          description:  t('市场 stdio 连接器声明的凭据字段值；只保存在本机，不写入目录'),\n        },\n        headersJson: { type: 'string', description: t('额外静态头（JSON 对象字符串）') },\n        scope: { type: 'string', enum: ['global', 'project'], description: t('目标作用域；新连接省略时使用 global，已有 key 保留原范围') },\n        workspaceId: { type: 'string', description: t('scope=project 时必填') },\n      },\n      // Provider compatibility: no root-level unions. api.configure validates each mode before saving.\n      additionalProperties: false,\n    },\n    output: resultOutput,\n    async execute(args) {\n      return api.configure(args ?? {});\n    },\n  });\n\n  reg({\n    name: 'mcp_connector_import_json',\n    description: t('粘贴 JSON 批量导入外部 MCP 连接。支持 HTTP/SSE 与 stdio（command/args/env/cwd）：{ \"mcpServers\": { \"name\": {...} } } 或 { \"connections\": [ {...} ] }。局域网明文 HTTP 需在对应条目显式填写 allowInsecurePrivateNetwork=true。整体预校验，任一非法整体拒绝。'),\n    parameters: {\n      type: 'object',\n      properties: {\n        json: { type: 'string', description: t('JSON 配置文本') },\n        scope: { type: 'string', enum: ['global', 'project'], description: t('目标作用域；新 key 省略时使用 global，已有 key 保留原范围') },\n        workspaceId: { type: 'string', description: t('scope=project 时必填') },\n      },\n      required: ['json'],\n      additionalProperties: false,\n    },\n    output: resultOutput,\n    async execute(args) {\n      return api.importJson(args.json, args);\n    },\n  });\n\n  reg({\n    name: 'mcp_connector_export_config',\n    description: t('导出全部 MCP 连接的可携带脱敏 JSON。不会返回 Token、API Key、Header/env 值、OAuth Grant、stdio 参数或本地路径；带占位符的字段必须在目标本机重填，OAuth 连接必须重新授权。'),\n    parameters: noArgs,\n    output: exportOutput,\n    async execute() {\n      return api.exportConfig();\n    },\n  });\n\n  reg({\n    name: 'mcp_connector_snapshot',\n    description: t('管理本机连接配置快照：list 列出、create 手动创建、preview